/**
 * Top-level FFI error. Coarse by design — the seam maps these to health/errors,
 * and the backup variant never distinguishes wrong-passphrase from tampering.
 */
public enum LarkError {

    
    
    case Wallet(msg: String
    )
    case Backup(msg: String
    )
    case Invalid(msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLarkError: FfiConverterRustBuffer {
    typealias SwiftType = LarkError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LarkError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Wallet(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Backup(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Invalid(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LarkError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Wallet(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Backup(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Invalid(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


